use super::*;
#[test]
fn original_branch_checkpoint_borrows_wide_sources_and_matches_independent_commitment(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("fixture.json")).unwrap();let saved=fixture["savedAt"].as_str().unwrap();let timestamp=fixture["timestamp"].as_str().unwrap();let parent=fixture["parent"].as_str().unwrap();let pending_id=fixture["pendingId"].as_str().unwrap();let pending=vec![fixture["pattern"].as_str().unwrap().repeat(fixture["repeat"].as_u64().unwrap()as usize),"edit-2".into()];let ids=vec!["change-old".into(),"change-described".into(),pending_id.into()];let mut changes=ArtifactHistoryLedger::new();for(id,description,edit)in[("change-old",None,"edit-old"),("change-described",Some("quoted \"\nλ"),"edit-described")]{changes.try_push(Change{id:id.into(),edit_ids:vec![edit.into()],description:description.map(str::to_owned),saved_at:saved.into()}).unwrap();}
 let input=OriginalPendingCheckpointInput{generation:31,parent:Some(parent),prior_change_ids:&ids[..2],changes:&changes,pending_id,pending_edits:&pending,pending_description:None,saved_at:saved,timestamp,message:None,authors:&[]};let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:1};
 for cut in [Some(0),Some(1),Some(7),Some(50),Some(150),None]{let mut owner=OriginalPendingCheckpointIdentity::default();assert!(owner.demands().copy_bytes<=4096,"fixed commitment event exceeds body policy: {:?}",owner.demands());for step in 0..100000{if owner.digest().is_some()||cut==Some(step){break}let d=owner.demands();for axis in 0..5{let mut denied=grant;let limit=match axis{0=>&mut denied.maximum_items,1=>&mut denied.maximum_copy_bytes,2=>&mut denied.maximum_capacity_bytes,3=>&mut denied.maximum_release_bytes,_=>&mut denied.maximum_depth};let demand=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if demand==0{continue}*limit=demand-1;let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,denied).unwrap());assert_eq!(p,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(p.fits(grant));assert!(step<99999);}
  if cut.is_none(){let digest=owner.digest().expect("original borrowed commitment completes");let actual=digest.iter().map(|byte|format!("{byte:02x}")).collect::<String>();assert_eq!(actual,fixture["digest"].as_str().unwrap());let reference=content_addressed_checkpoint_id_with_pending_change(Some(parent),&ids,&changes,pending_id,&pending,None,saved,None,&[],timestamp,&[]);assert_eq!(reference,format!("ck-{}",&actual[..16]));}
  if !owner.terminal_is_empty(){let changed=OriginalPendingCheckpointInput{generation:32,..input};assert!(owner.advance(&changed,grant).is_err());}let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant));assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(owner.terminal_is_empty());
 }
 while changes.pop().is_some(){}
}

#[test]
fn original_pending_edits_match_sql_selection_and_retire_every_partial_canonical_birth(){
 use super::pending::OriginalPendingEditIds;
 let f:serde_json::Value=serde_json::from_str(include_str!("pending.json")).unwrap();let mut applied=crate::HistoryPageStack::empty();for id in f["applied"].as_array().unwrap(){applied.try_push(id.as_str().unwrap().to_owned()).unwrap();}let mut changes=ArtifactHistoryLedger::new();for(index,row)in f["committed"].as_array().unwrap().iter().enumerate(){changes.try_push(Change{id:format!("change-{index}"),edit_ids:row.as_array().unwrap().iter().map(|id|id.as_str().unwrap().to_owned()).collect(),description:None,saved_at:"time".into()}).unwrap();}
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:65536,maximum_depth:4096};
 for cut in [Some(0),Some(1),Some(9),Some(23),Some(40),None]{let mut owner=OriginalPendingEditIds::default();for step in 0..10000{if cut==Some(step)||owner.ready(){break}let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(31,&applied,&changes,grant,|_|Ok(())).unwrap());assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(step<9999);}if cut.is_none(){let expected:Vec<_>=f["pending"].as_array().unwrap().iter().map(|id|id.as_str().unwrap()).collect();assert_eq!(owner.prepared().unwrap().iter().map(String::as_str).collect::<Vec<_>>(),expected);}for step in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demands(4096).unwrap();let closing=RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes.max(d.copy_bytes),maximum_capacity_bytes:grant.maximum_capacity_bytes.max(d.capacity_bytes),..grant};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(closing).unwrap());let p=result.progress();assert!(p.fits(closing));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(step<99999);}assert!(owner.terminal_is_empty());}
 while changes.pop().is_some(){}while applied.pop().is_some(){}while applied.release_empty_page(){}
}

#[test]
fn original_branch_facts_retain_every_denied_owner_and_physically_close_composition_fields(){
 fn close<T:semio_framework_value::retirement::RetireOwned>(value:T){use semio_framework_value::{RetainedCloneStep,ErasedSnapshotRetirement};let mut input=Some(value);let mut owner=semio_framework_value::retained_clone::RetainedCloneClose::default();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:65536,maximum_depth:4096};let d=owner.next_owner_demands::<T>(true,&None,4096).unwrap();for axis in 0..5{let amount=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if amount==0{continue}let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=amount-1,2=>denied.maximum_capacity_bytes=amount-1,3=>denied.maximum_release_bytes=amount-1,_=>denied.maximum_depth=amount-1};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.begin_granted(&mut input,denied).unwrap());assert!(result.is_none()||result.unwrap().progress()==Default::default());assert!(input.is_some());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
  let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.begin_granted(&mut input,grant).unwrap().unwrap());let p=result.progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(input.is_none());for index in 0..100000{if owner.is_empty(){break}let d=RetirementDemand{copy_bytes:owner.next_copy_byte_demand().unwrap(),capacity_bytes:owner.next_capacity_byte_demand(4096).unwrap(),release_bytes:owner.next_release_byte_demand().unwrap(),depth:owner.next_depth_demand().unwrap()};assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step_granted(grant).unwrap());let p=match result{RetainedCloneStep::Complete(p)|RetainedCloneStep::Progress(p)=>p};assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(index<99999);}assert!(owner.is_empty());}
 close(Change{id:"change".into(),edit_ids:vec!["edit".into()],description:Some("description".into()),saved_at:"time".into()});close(crate::Alternative{id:"alternative".into(),name:"Alternative λ".into(),checkpoint_ids:vec!["ck".into()]});close(crate::Checkpoint{id:"ck".into(),change_ids:vec!["change".into()],parent_id:Some("parent".into()),authors:vec![Author{id:"actor".into(),name:"Actor".into(),avatar:Some("avatar".into())}],message:Some("message".into()),timestamp:"time".into(),composition_pins:vec![CompositionPin{child_ref:semio_framework_artifact_reference::ArtifactRef{artifact_id:"child".into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"energy".into(),standard:"semio".into(),subset:"*".into()}},checkpoint_id:"child-ck".into()}]});
}

#[test]
fn original_branch_fact_birth_adopts_exact_pending_vector_and_closes_partial_canonical_rows(){
 use super::facts::{OriginalBranchFactBirth,OriginalBranchFactInput};use semio_framework_value::ToValue;
 let f:serde_json::Value=serde_json::from_str(include_str!("facts.json")).unwrap();let parent=crate::Checkpoint{id:f["parent"]["id"].as_str().unwrap().into(),change_ids:f["parent"]["changeIds"].as_array().unwrap().iter().map(|id|id.as_str().unwrap().into()).collect(),parent_id:None,authors:Vec::new(),message:None,timestamp:"old".into(),composition_pins:Vec::new()};let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:65536,maximum_depth:4096};
 for create in [false,true]{for parent in [None,Some(&parent)]{for cut in [Some(0),Some(1),Some(4),Some(13),Some(30),None]{let mut pending=Some(if create{f["pending"].as_array().unwrap().iter().map(|id|id.as_str().unwrap().to_owned()).collect::<Vec<_>>()}else{let mut v=Vec::new();v.reserve_exact(5);v});let pointer=pending.as_ref().unwrap().as_ptr();let input=OriginalBranchFactInput{generation:31,parent,change_id:f["changeId"].as_str().unwrap(),checkpoint_id:f["checkpointId"].as_str().unwrap(),alternative_id:f["alternativeId"].as_str().unwrap(),name:f["name"].as_str().unwrap(),saved_at:f["savedAt"].as_str().unwrap(),timestamp:f["timestamp"].as_str().unwrap(),create_checkpoint:create};let mut owner=OriginalBranchFactBirth::default();for step in 0..10000{if cut==Some(step)||owner.ready(){break}let d=owner.demands(&input).unwrap();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096);for axis in 0..5{let amount=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if amount==0{continue}let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=amount-1,2=>denied.maximum_capacity_bytes=amount-1,3=>denied.maximum_release_bytes=amount-1,_=>denied.maximum_depth=amount-1};let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,&mut pending,denied,|_|Ok(())).unwrap());assert_eq!(p,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,&mut pending,grant,|_|Ok(())).unwrap());assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(step<9999);}if cut.is_none(){let facts=owner.prepared().expect("actual canonical facts complete");let alternative=semio_framework_pack_json::to_json_string(&facts.alternative);assert_eq!(serde_json::from_str::<serde_json::Value>(&alternative).unwrap(),serde_json::json!({"id":f["alternativeId"],"name":f["name"],"checkpointIds":[f["checkpointId"]]}));if create{let(change,checkpoint)=facts.checkpoint.as_ref().unwrap();assert_eq!(change.edit_ids.as_ptr(),pointer);let mut change_ids=parent.map_or(Vec::new(),|p|p.change_ids.clone());change_ids.push(input.change_id.into());assert_eq!(checkpoint.change_ids,change_ids);assert_eq!(checkpoint.parent_id.as_deref(),parent.map(|p|p.id.as_str()));assert_eq!(change.edit_ids,f["pending"].as_array().unwrap().iter().map(|id|id.as_str().unwrap()).collect::<Vec<_>>());let encoded=semio_framework_pack_json::to_json_string(change);assert_eq!(serde_json::from_str::<serde_json::Value>(&encoded).unwrap(),serde_json::json!({"id":f["changeId"],"editIds":f["pending"],"savedAt":f["savedAt"]}));}else{assert!(facts.checkpoint.is_none());}}
 for step in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demands(4096).unwrap();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant).unwrap());let p=result.progress();assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(step<99999);}assert!(owner.terminal_is_empty());}}}
}
